import { AnalysisResultSubscriber } from '../../../../public/typings/subscription'
import { AnalysisResultEntity } from './analysisResultEntity'

/**
 * Input for `AnalysisResultService.list` method.
 *
 * @interface ListAnalysisResultsInput
 * @property {string} virtualPresenceId The virtual presence to list analysis results for.
 * @property {number} limit Number of records to return.
 * @property {string} nextToken A token generated by a previous call to `AnalysisResultService.list`.
 *  This allows for pagination.
 */
export interface ListAnalysisResultsInput {
  virtualPresenceId: string
  limit?: number
  nextToken?: string
}

/**
 * Output for `AnalysisResultService.list` method.
 *
 * @interface ListAnalysisResultsOutput
 * @property {AnalysisResultEntity[]} analysisResults The list of analysis results retrieved in this query.
 * @property {string} nextToken A token generated by a previous call. This allows for pagination.
 */
export interface ListAnalysisResultsOutput {
  analysisResults: AnalysisResultEntity[]
  nextToken?: string
}

/**
 * Input for `AnalysisResultService.subscribe` method.
 *
 * @interface SubscribeToAnalysisResultInput
 * @property {string} subscriptionId A unique identifier for this subscription.
 * @property {string} owner The identifier of the owner to subscribe for.
 * @property {AnalysisResultSubscriber} subscriber The subscriber to receive events.
 */
export interface SubscribeToAnalysisResultInput {
  subscriptionId: string
  owner: string
  subscriber: AnalysisResultSubscriber
}

/**
 * Core entity representation of an analysis result service used in business logic.
 * Used to perform CRUD operations for analysis results.
 *
 * @interface AnalysisResultService
 */
export interface AnalysisResultService {
  /**
   * Retrieve a single analysis result by ID.
   *
   * @param {string} id The unique identifier of the analysis result.
   * @returns {AnalysisResultEntity | undefined} The analysis result, or undefined if not found.
   */
  get(id: string): Promise<AnalysisResultEntity | undefined>

  /**
   * Retrieve a list of analysis results for a virtual presence.
   *
   * @param {ListAnalysisResultsInput} input Parameters used to list analysis results.
   * @returns {ListAnalysisResultsOutput} A list of analysis results matching the search criteria.
   *  Can be empty if no analysis results found.
   */
  list(input: ListAnalysisResultsInput): Promise<ListAnalysisResultsOutput>

  /**
   * Subscribe to analysis result state events.
   *
   * @param {SubscribeToAnalysisResultInput} input Parameters used to subscribe to
   *  analysis result state events.
   */
  subscribe(input: SubscribeToAnalysisResultInput): Promise<void>

  /**
   * Unsubscribe from analysis result state events.
   *
   * @param {string} subscriptionId The unique identifier of the subscription to unsubscribe from.
   */
  unsubscribe(subscriptionId: string): void
}
